const stageNames: Record<string, string> = { BRIEF: 'Brief', SOURCE: 'Fuentes', INGEST: 'Preparación', DIRECTOR_TREATMENT: 'Tratamiento', CONCEPT_REVIEW: 'Concepto', CREATIVE_GATE: 'Revisión creativa', PROVIDER_PRODUCTION: 'Producción', TECHNICAL_QA: 'Calidad técnica', CRITIC: 'Revisión crítica', FIXER: 'Ajustes', INDEPENDENT_VERIFIER: 'Verificación', COMPLIANCE: 'Conformidad', RELEASE: 'Entrega' };
const simpleJourney=[
 {label:'Preparar',stages:['BRIEF','SOURCE','INGEST','DIRECTOR_TREATMENT','CONCEPT_REVIEW','CREATIVE_GATE']},
 {label:'Crear',stages:['PROVIDER_PRODUCTION','TECHNICAL_QA','FIXER']},
 {label:'Revisar',stages:['CRITIC','INDEPENDENT_VERIFIER','COMPLIANCE']},
 {label:'Entregar',stages:['RELEASE']},
] as const;
function simpleJourneyIndex(stage:string,status:string){if(status==='RELEASED')return 3;const index=simpleJourney.findIndex(group=>(group.stages as readonly string[]).includes(stage));return index<0?0:index}
